PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geosparql: <http://www.opengis.net/ont/geosparql#>

SELECT ?distanceKm
WHERE {
  GRAPH <hydroturtle/quadica> {
    # Highest and lowest values for annual median dissolved organic carbon in 2010
    {
      SELECT ?stationHighest ?vHigh WHERE {
        ?obsHigh a sosa:Observation ;
                  sosa:observedProperty ?propHigh ;
                  sosa:hasFeatureOfInterest ?stationHighest ;
                  sosa:resultTime ?tHigh ;
                  sosa:hasResult ?rvHigh .
        ?rvHigh qudt:numericValue ?vHigh .
        FILTER(YEAR(?tHigh) = 2010)

        # Dissolved organic carbon
        FILTER(?propHigh = hyobs:ddhad)

      }
      ORDER BY DESC(?vHigh)
      LIMIT 1
    }
    {
      SELECT ?stationLowest ?vLow WHERE {
        ?obsLow a sosa:Observation ;
                 sosa:observedProperty ?propLow ;
                 sosa:hasFeatureOfInterest ?stationLowest ;
                 sosa:resultTime ?tLow ;
                 sosa:hasResult ?rvLow .
        ?rvLow qudt:numericValue ?vLow .
        FILTER(YEAR(?tLow) = 2010)

        FILTER(?propLow = hyobs:ddhad)
      }
      ORDER BY ASC(?vLow)
      LIMIT 1
    }

    # Geometry for each station
    ?stationHighest geosparql:hasGeometry ?geomHigh .
    ?geomHigh geosparql:asWKT ?wktHigh .

    ?stationLowest geosparql:hasGeometry ?geomLow .
    ?geomLow geosparql:asWKT ?wktLow .

    # Distance (requires GeoSPARQL functions; if unsupported, this may fail)
    BIND(geof:distance(?wktHigh, ?wktLow, uom:metre) / 1000 AS ?distanceKm)
  }
}

